// Pure-compute text analysis — no network, no credentials.
const item = $input.first().json;
const text = String(item.text || '');

const words = (text.match(/\b[\w']+\b/g) || []);
const wordCount = words.length;
const charCount = text.length;
const charCountNoSpaces = text.replace(/\s+/g, '').length;
const sentenceCount = (text.match(/[.!?]+/g) || []).length || 1;

// Reading time at 200 wpm.
const readingMinutes = Math.max(1, Math.round(wordCount / 200));

// Top keywords (stop-word filtered, length >= 4).
const STOP = new Set(['this','that','with','from','have','will','your','into','than','then','they','them','and','the','for','are','but','not','out','its','was','were']);
const freq = {};
for (const w of words.map(w => w.toLowerCase())) {
  if (w.length < 4 || STOP.has(w)) continue;
  freq[w] = (freq[w] || 0) + 1;
}
const topKeywords = Object.entries(freq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([word, count]) => ({ word, count }));

// URL-safe slug from the first 8 words.
const slug = words.slice(0, 8).join(' ')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/(^-|-$)/g, '');

return [{ json: {
  wordCount,
  charCount,
  charCountNoSpaces,
  sentenceCount,
  avgWordsPerSentence: Math.round((wordCount / sentenceCount) * 10) / 10,
  readingMinutes,
  topKeywords,
  slug,
} }];
